const FIELDS = { place: ['name', 'about'], event: ['title', 'about'], person: ['name', 'about'], era: ['name'], journey: ['name', 'note'] };
export const L10N = {};
for (const [lang, kinds] of Object.entries(RAW)) {
  L10N[lang] = {};
  for (const [kind, items] of Object.entries(kinds)) {
    L10N[lang][kind] = {};
    for (const [id, arr] of Object.entries(items)) L10N[lang][kind][id] = Object.fromEntries(FIELDS[kind].map((f, i) => [f, arr[i]]));
  }
}

// Dates like "c. 1446 BC (or c. 1270 BC)", "AD 70", "The beginning".
const DATE = {
  fr: { bc: 'av. J.-C.', ad: 'apr. J.-C.', c: 'v.', or: 'ou', beginning: 'Au commencement', early: 'Histoire primitive' },
  pt: { bc: 'a.C.', ad: 'd.C.', c: 'c.', or: 'ou', beginning: 'O princípio', early: 'História primitiva' },
  es: { bc: 'a. C.', ad: 'd. C.', c: 'c.', or: 'o', beginning: 'El principio', early: 'Historia primitiva' },
};
export function localDate(s, lang) {
  const d = DATE[lang]; if (!d) return s;
  if (s === 'The beginning') return d.beginning;
  if (s === 'Early history') return d.early;
  return s.replace(/\bAD (\d+)/g, `$1 ${d.ad}`).replace(/\bBC\b/g, d.bc).replace(/\bc\. /g, d.c + ' ').replace(/\bor\b/g, d.or);
}
for (const lang of Object.keys(RAW)) for (const e of EVENTS) { const o = (L10N[lang].event[e.id] ||= {}); o.date = localDate(e.date, lang); }
